'use strict';

// MODULES //

var zeros = require( '@stdlib/array/base/zeros' );


// MAIN //

/**
* Creates a callback that augments loop indices with provided index positions and invokes a given callback.
*
* @private
* @param {Array} loopIndices - outer loop indices.
* @param {Array} indicesPos - list of positions where to insert the inner loop indices.
* @param {Object} xref - reference to the input ndarray.
* @param {Function} clbk - callback function.
* @param {thisArg} thisArg - callback execution context.
* @returns {Function} wrapped callback function.
*/
function wrap( loopIndices, indicesPos, xref, clbk, thisArg ) {
	var idx;
	var io;
	var ii;
	var i;

	idx = zeros( loopIndices.length + indicesPos.length );
	io = 0;
	ii = 0;
	for ( i = 0; i < idx.length; i++ ) {
		if ( ii < indicesPos.length && i === indicesPos[ ii ] ) {
			ii += 1;
			continue;
		}
		idx[ i ] = loopIndices[ io ];
		io += 1;
	}
	return wrapped;

	/**
	* Augments the provided index array and calls the original callback.
	*
	* @private
	* @param {*} v - value.
	* @param {Array} indices - indices of the inner loop.
	* @returns {*} result of the callback function.
	*/
	function wrapped( v, indices ) {
		for ( i = 0; i < indices.length; i++ ) {
			idx[ indicesPos[ i ] ] = indices[ i ];
		}
		return clbk.call( thisArg, v, idx.slice(), xref );
	}
}


// EXPORTS //

module.exports = wrap;
